fn readb(mut addr: *const ()) -> u8 {
let mut ret: u8 = 0;
unsafe {
let __t0: u32;
core::arch::asm!("movb ({1:r}),{0:l}", lateout(reg) __t0, in(reg) addr as *mut u8, options(nostack, att_syntax));
ret = unsafe { core::mem::transmute::<u8, u8>(__t0 as u8) };
}
ret
}

