fn i2c_get_adapdata(adap: *const i2c_adapter) -> *mut () {
dev_get_drvdata(unsafe { core::ptr::addr_of!((*adap).dev) })
}

fn i2c_set_adapdata(adap: *mut i2c_adapter, data: *mut ()) {
dev_set_drvdata(unsafe { core::ptr::addr_of_mut!((*adap).dev) }, data);
}

// Adapter locking functions, exported for shared pin cases
fn i2c_lock_bus(adapter: *mut i2c_adapter, flags: u32) {
unsafe { unsafe { (*(*adapter).lock_ops).lock_bus }.unwrap()(adapter, flags) };
}

fn i2c_unlock_bus(adapter: *mut i2c_adapter, flags: u32) {
unsafe { unsafe { (*(*adapter).lock_ops).unlock_bus }.unwrap()(adapter, flags) };
}

fn i2c_mark_adapter_suspended(adap: *mut i2c_adapter) {
i2c_lock_bus(adap, BIT!(0i32) as u32);
set_bit(0i64, (unsafe { core::ptr::addr_of_mut!((*adap).locked_flags) }) as *mut u64);
i2c_unlock_bus(adap, BIT!(0i32) as u32);
}

fn i2c_mark_adapter_resumed(adap: *mut i2c_adapter) {
i2c_lock_bus(adap, BIT!(0i32) as u32);
clear_bit(0i64, (unsafe { core::ptr::addr_of_mut!((*adap).locked_flags) }) as *mut u64);
i2c_unlock_bus(adap, BIT!(0i32) as u32);
}

