// Alder Lake-P (PCH)		0x51a3	32	hard	yes	yes	yes
// Alder Lake-M (PCH)		0x54a3	32	hard	yes	yes	yes
// Raptor Lake-S (PCH)		0x7a23	32	hard	yes	yes	yes
// Meteor Lake-P (SOC)		0x7e22	32	hard	yes	yes	yes
// Meteor Lake SoC-S (SOC)	0xae22	32	hard	yes	yes	yes
// Meteor Lake PCH-S (PCH)	0x7f23	32	hard	yes	yes	yes
// Birch Stream (SOC)		0x5796	32	hard	yes	yes	yes
// Arrow Lake-H (SOC)		0x7722	32	hard	yes	yes	yes
// Panther Lake-H (SOC)		0xe322	32	hard	yes	yes	yes
// Panther Lake-P (SOC)		0xe422	32	hard	yes	yes	yes
// Wildcat Lake-U (SOC)		0x4d22	32	hard	yes	yes	yes
// Diamond Rapids (SOC)		0x5827	32	hard	yes	yes	yes
// Nova Lake-S (PCH)		0x6e23	32	hard	yes	yes	yes
//
// Features supported by this driver:
// Software PEC				no
// Hardware PEC				yes
// Block buffer				yes
// Block process call transaction	yes
// I2C block read transaction		yes (doesn't use the block buffer)
// Target mode				no
// SMBus Host Notify			yes
// Interrupt processing			yes
//
// See the file Documentation/i2c/busses/i2c-i801.rst for details.
// ICH3 and later
// PCI Address Constants
// Host configuration bits for SMBHSTCFG
// TCO configuration bits for TCOCTL
// Auxiliary status register bits, ICH4+ only
// Auxiliary control register bits, ICH4+ only
// I801 command constants
// ICH5 and later
// I801 Host Control register bits
// ICH3 and later
// I801 Hosts Status register bits
// Host Notify Status register bits
// Host Notify Command register bits
// Older devices have their ID defined in <linux/pci_ids.h>
// Patsburg also has three 'Integrated Device Function' SMBus controllers
#[repr(C)]
#[derive(Clone, Copy)]
struct i801_priv {
    adapter: i2c_adapter,
    smba: *mut (),
    original_hstcfg: u8,
    original_hstcnt: u8,
    original_slvcmd: u8,
    pci_dev: *mut pci_dev,
    features: u32,
    /// isr processing
    done: completion,
    status: u8,
    /// Command state used by isr for byte-by-byte block transactions
    cmd: u8,
    is_read: bool,
    count: i32,
    len: i32,
    data: *mut u8,
    tco_pdev: *mut platform_device,
    /// If set to true the host controller registers are reserved for
    /// ACPI AML use. Needs extra protection by acpi_lock.
    acpi_reserved: bool,
    acpi_lock: mutex,
}


